{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. -#}
{%- set v_login = og_def(p['login'], none) -%}
{%- set v_loginHref = og_def(p['loginHref'], none) -%}
{%- set v_cta = og_def(p['cta'], none) -%}
{%- set v_ctaHref = og_def(p['ctaHref'], none) -%}
{%- set v_actions = og_def(p['actions'], 'cta') -%}
{%- set v_tone = og_def(p['tone'], 'default') -%}
{%- set v_themeLabel = og_def(p['themeLabel'], none) -%}
{%- if og_t(v_login) %}
  {%- set c_1 -%}
    {{ og_text(v_login) }}
  {%- endset -%}
  {{ og_include('compose/button.html.j2', {'p': {'Variant': 'ghost', 'Size': 'sm', 'Href': og_url(og_s(v_loginHref)), 'Class': og_s(('text-background hover:bg-background/10' if og_t(og_eq(v_tone, 'inverse')) else ''))}, 'children': c_1}) }}
{%- endif %}
{%- if og_t(og_and([og_eq(v_actions, 'cta'), v_cta])) %}
  {%- set c_2 -%}
    {{ og_text(v_cta) }}
  {%- endset -%}
  {{ og_include('compose/button.html.j2', {'p': {'Variant': og_s(('secondary' if og_t(og_eq(v_tone, 'inverse')) else 'default')), 'Size': 'sm', 'Href': og_url(og_s(v_ctaHref))}, 'children': c_2}) }}
{%- endif %}
{%- if og_t(v_themeLabel) %}
  {%- set c_3 -%}
    {{ og_text(v_themeLabel) }}
  {%- endset -%}
  {{ og_include('compose/button.html.j2', {'p': {'Variant': 'outline', 'Size': 'sm'}, 'children': c_3}) }}
{%- endif %}
